using Xunit;

public class U09_AlarmsTest
{
    [Fact]
    public void Controller_Reports_Proximal_Tube_Connected()
    {
        // Arrange
        var controller = new AlarmsController();

        // Act
        var isConnected = controller.IsProximalTubeConnected();

        // Assert
        Assert.True(isConnected);
    }

    [Fact]
    public void GUI_Computes_Proximal_Tube_Disconnect_Alarm()
    {
        // Arrange
        var gui = new AlarmsGUI();

        // Act
        gui.ComputeProximalTubeDisconnectAlarm();

        // Assert
        Assert.True(gui.IsProximalTubeDisconnectAlarmActive());
    }

    [Fact]
    public void Obstruction_Alarm_Has_High_Priority()
    {
        // Arrange
        var alarm = new Alarm(AlarmType.Obstruction);

        // Assert
        Assert.Equal(AlarmPriority.High, alarm.Priority);
    }

    [Fact]
    public void GUI_Detects_Obstruction_When_VTI_LessThan_100ml()
    {
        // Arrange
        var gui = new AlarmsGUI();

        // Act
        gui.DetectObstruction(90);

        // Assert
        Assert.True(gui.IsObstructionDetected());
    }

    [Fact]
    public void GUI_Inactivates_Obstruction_Alarm_When_VTI_GreaterThan_100ml()
    {
        // Arrange
        var gui = new AlarmsGUI();

        // Act
        gui.DetectObstruction(110);

        // Assert
        Assert.False(gui.IsObstructionDetected());
    }
}
